	public static void SaveReportLog_ContestNet(uint result, uint category, uint level, uint monsNo, uint costume, uint wazaId, uint score, uint bestPerformer) {
        PlayReportEvent prepo = Events[(int)EventID.CONTEST_NET];
        prepo.AddLong("trainer_id", PlayerWork.playerStatus.id);
        prepo.AddLong("result", result);
        prepo.AddLong("category", category);
        prepo.AddLong("level", level);
        prepo.AddLong("monsno", monsNo);
        prepo.AddLong("costume", costume);
        prepo.AddLong("waza", wazaId);
        prepo.AddLong("score", score);
        prepo.AddLong("best_performer", bestPerformer);
        prepo.SaveEvent();
    }
	public static void SaveReportLog_BallDecoration(uint[] sealId, uint sealIdNum) {
        PlayReportEvent prepo = Events[(int)EventID.BALL_DECORATION];
        prepo.AddLong("trainer_id", PlayerWork.playerStatus.id);
        for (int i = 0; i < 20; i++)
            prepo.AddLong(string.Format("seal{0}", i), i < sealIdNum ? sealId[i] : 0);
        prepo.SaveEvent();
    }
	public static void SaveReportLog_Custome() {
        PlayReportEvent prepo = Events[(int)EventID.COSTUME];
        prepo.AddLong("trainer_id", PlayerWork.playerStatus.id);
        prepo.AddLong("costume_id", PlayerWork.playerStatus.fashion);
        prepo.SaveEvent();
    }
	public static void SaveReportLog_Tsurearuki() {
        // @02ce8cb0: nothing is reported when the walking partner index is outside the party
        int index = PlayerWork.playerStatus.turewalkMemberIndex;
        PokeParty party = PlayerWork.playerParty;
        if (index < 0 || index >= party.GetMemberCount())
            return;

        PlayReportEvent prepo = Events[(int)EventID.TSUREARUKI];
        PokemonParam pp = party.GetMemberPointerConst((uint)index);
        prepo.AddLong("trainer_id", PlayerWork.playerStatus.id);
        prepo.AddLong("monsno", (int)pp.GetMonsNo());
        prepo.SaveEvent();
    }
	public static void SaveReportLog_PokemonId(uint monsNo, uint monsForm, uint captureMethod, uint shiny) {
        PlayReportEvent prepo = Events[(int)EventID.POKEMON_ID];
        prepo.AddLong("trainer_id", PlayerWork.playerStatus.id);
        prepo.AddLong("monsno", monsNo);
        prepo.AddLong("mons_form", monsForm);
        prepo.AddLong("captureMethod", captureMethod);
        prepo.AddLong("shiny", shiny);
        prepo.SaveEvent();
    }
