        prepo.AddLong("trainer_id", PlayerWork.playerStatus.id);
        prepo.AddLong("lithography_id", lithographyId);
        prepo.SaveEvent();
    }
	public static void StartWildBattle(global::PlayReportManager.eCaptureType type) {
        CaptureType = type;
        PLAYREPORT_DATA data = PlayerWork.playReportData;
        data.wild_pokemon_encount++;
        PlayerWork.playReportData = data;
    }
	public static void AddCapture() {
        if (CaptureType == eCaptureType.None)
            return;

        PLAYREPORT_DATA data = PlayerWork.playReportData;
        if (CaptureType == eCaptureType.Wild)
            data.capture_wild++;
        else if (CaptureType == eCaptureType.Symbol)
            data.capture_symbol++;
        else if (CaptureType == eCaptureType.Fishing)
            data.capture_fishing++;
        CaptureType = eCaptureType.None;
        PlayerWork.playReportData = data;
    }
	public static void AddBattle() {
        PLAYREPORT_DATA data = PlayerWork.playReportData;
        data.total_all_battle++;
        PlayerWork.playReportData = data;
    }
	public static void AddZenmetu() {
        PLAYREPORT_DATA data = PlayerWork.playReportData;
        data.btl_lose_cnt++;
        PlayerWork.playReportData = data;
    }
	public static void AddMoney(int add) {
        PLAYREPORT_DATA data = PlayerWork.playReportData;
        data.total_money += add;
        PlayerWork.playReportData = data;
    }
	public static void PoketoreCount() {
        // @02ce9ce0: the Poke Radar chain is taken from the first Poketch poketore slot
        PLAYREPORT_DATA data = PlayerWork.playReportData;
        data.chain_encount = PlayerWork.poketoreCountArray.data[0].count;
        PlayerWork.playReportData = data;
    }
	public static void GoUnderGround() {
        PLAYREPORT_DATA data = PlayerWork.playReportData;
        data.go_to_underground++;
        PlayerWork.playReportData = data;
    }
	public static void NpcKoukan() {
        PLAYREPORT_DATA data = PlayerWork.playReportData;
        data.npc_trade++;
        PlayerWork.playReportData = data;
    }
	public static void AddWalkCnt(int walk) {
        PLAYREPORT_DATA data = PlayerWork.playReportData;
        data.total_walk += walk;
        PlayerWork.playReportData = data;
    }
